/// A table of unsigned byte displacements from the dispatcher-selected base.
#[derive(Debug)]
pub struct SwitchTable {
    pub file: u32,
    pub entry_bytes: u8,
    pub first_case: u8,
    pub targets: &'static [u32],
}

impl SwitchTable {
    pub fn emit(&self) -> Result<Vec<u8>, String> {
        let mut bytes = Vec::new();
        for &target in self.targets {
            if target & 1 != 0 || !CODE.iter().any(|(pc, _)| *pc == target) {
                return Err(format!("switch target {target:#x} is not a source instruction boundary"));
            }
            let delta = target.checked_sub(self.file).ok_or("switch target precedes unsigned base")?;
            match self.entry_bytes {
                1 => bytes.push(u8::try_from(delta).map_err(|_| "switch byte displacement overflow")?),
                2 => bytes.extend_from_slice(&u16::try_from(delta).map_err(|_| "switch halfword displacement overflow")?.to_le_bytes()),
                _ => return Err("switch entry width must be one or two bytes".into()),
            }
        }
        Ok(bytes)
    }
}

pub const SWITCH_TABLES: &[SwitchTable] = &[

    // Loads byte [r6+1], subtracts 3, tests unsigned index <9, loads u16 at r15 + index*2 through EX9 slot423, adds r15 through slot52, jumps to r15.
    SwitchTable { file: 0x11f50, entry_bytes: 2, first_case: 3, targets: &[0x11f62, 0x120a2, 0x12540, 0x121a0, 0x12540, 0x122bc, 0x1231a, 0x123f4, 0x1245c] },
    // Computes index r7-1 and tests unsigned index <15; loads u16 at r15+index*2 explicitly, adds r15 through EX9 slot158, jumps to r15.
    SwitchTable { file: 0x125ac, entry_bytes: 2, first_case: 1, targets: &[0x125ca, 0x12610, 0x126de, 0x1280a, 0x12650, 0x128d2, 0x128d2, 0x128d2, 0x128d2, 0x1282c, 0x12860, 0x128b4, 0x128d2, 0x128d2, 0x128d6] },
    // Loads state byte [r0+0x43], tests unsigned state <10; loads u8 at r15+index through EX9 slot467, adds table base through slot158, jumps to r15. Cases write normalized state byte and flag at +0x46.
    SwitchTable { file: 0x13d14, entry_bytes: 1, first_case: 0, targets: &[0x13d1e, 0x13d22, 0x13d3a, 0x13d3a, 0x13d2a, 0x13d3a, 0x13d2e, 0x13d3a, 0x13d3a, 0x13d26] },
    // Tests unsigned selector r0<9, saves selector to r1, loads default pointer from GP-464; loads u8 offset through EX9 slot467, adds table base through slot158, jumps to r15. Most cases return base plus fixed stride offsets; index1 returns unchanged pointer.
    SwitchTable { file: 0x16f3c, entry_bytes: 1, first_case: 0, targets: &[0x16f46, 0x16f78, 0x16f4c, 0x16f52, 0x16f58, 0x16f5e, 0x16f64, 0x16f6a, 0x16f70] },
];

/// Regenerate all ordinary instructions, switch offsets and the one declared
/// alignment byte; fail at any unaccounted gap, overlap, or width change.
pub fn emit() -> Result<Vec<u8>, String> {
    let mut out = Vec::with_capacity((SOURCE_END - SOURCE_START) as usize);
    let mut index = 0;
    let mut pc = SOURCE_START;
    while pc < SOURCE_END {
        if let Some(&(at, op)) = CODE.get(index) {
            if at == pc {
                let bytes = op.encode(at)?;
                if bytes.len() != op.width() { return Err(format!("width mismatch at {at:#x}")); }
                pc = pc.checked_add(bytes.len() as u32).ok_or("source address overflow")?;
                out.extend_from_slice(&bytes);
                index += 1;
                continue;
            }
        }
        if let Some(table) = SWITCH_TABLES.iter().find(|t| t.file == pc) {
            let bytes = table.emit()?;
            pc += bytes.len() as u32;
            out.extend_from_slice(&bytes);
        } else if pc == 0x16f45 {
            out.push(0); // One declared padding byte after the nine-byte switch table.
            pc += 1;
        } else {
            return Err(format!("unaccounted hole or overlapping instruction at file {pc:#x}"));
        }
    }
    if pc != SOURCE_END || index != CODE.len() || pc > RESERVED_END {
        return Err("source boundary or instruction count disagreement".into());
    }
    Ok(out)
}

pub fn branch_target(op: Instruction) -> Option<u32> {
    match op {
        Beq(_, _, t) | Bne(_, _, t) | Beqc(_, _, t) | Bnec(_, _, t)
        | Beqz38(_, t) | Bnez38(_, t) | Beqs38(_, t) | Bnes38(_, t)
        | Beqz(_, t) | Bnez(_, t) | Bgez(_, t) | Bgtz(_, t) | Blez(_, t) | Bltz(_, t)
        | Beqzs8(t) | Bnezs8(t) | J8(t) | Jal(t) | J(t) | Ifcall(t) | Ifcall9(t) => Some(t),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_accounting_excludes_the_cross_owner_seam() {
        assert_eq!(SOURCE_START - RESERVED_START, 22);
        assert!(SOURCE_END <= RESERVED_END);
        assert_eq!(CODE.iter().map(|(_, i)| i.width()).sum::<usize>(), EXECUTABLE_BYTES);
        assert_eq!(SWITCH_TABLES.iter().map(|t| t.emit().unwrap().len()).sum::<usize>(), SWITCH_DATA_BYTES);
        assert_eq!(emit().unwrap().len(), EXECUTABLE_BYTES + SWITCH_DATA_BYTES + ALIGNMENT_BYTES);
    }

    #[test]
    fn branch_targets_do_not_enter_tables_or_split_instructions() {
        for &(at, op) in CODE {
            if let Some(t) = branch_target(op) {
                if (SOURCE_START..SOURCE_END).contains(&t) {
                    assert!(CODE.iter().any(|(pc, _)| *pc == t), "branch at {at:#x} targets noninstruction {t:#x}");
                }
            }
        }
    }

    #[test]
    fn switch_tables_have_the_proven_dispatch_domains() {
        assert_eq!(SWITCH_TABLES.iter().map(|t| (t.first_case, t.targets.len())).collect::<Vec<_>>(),
            vec![(3,9), (1,15), (0,10), (0,9)]);
        assert!(SwitchTable { file: 0x10016, entry_bytes: 1, first_case: 0, targets: &[0x101ac] }.emit().is_err());
        assert!(SwitchTable { file: 0x10016, entry_bytes: 2, first_case: 0, targets: &[0x10017] }.emit().is_err());
    }
}
